import{detectPackageManager}from"#setup/package-manager.js";import{createPromptCommandOutput,withPhase}from"#setup/cli/index.js";import{packageManagerInstallSucceeded,runPackageManagerInstall}from"#setup/primitives/pm/run.js";const defaultDeps={detectPackageManager,runPackageManagerInstall};async function installScaffoldDependencies(e){if(!e.changed||e.skip)return;let t=e.deps??defaultDeps,n=await t.detectPackageManager(e.projectPath),r=await withPhase(e.log,`Installing integration dependencies (${n.kind} install)...`,()=>t.runPackageManagerInstall(n.kind,e.projectPath,{onOutput:createPromptCommandOutput(e.log),signal:e.signal}));packageManagerInstallSucceeded(r)||e.log.warning(`Dependency installation failed. The integration stays unloadable until \`${n.kind} install\` or a deploy succeeds.`)}function reportOverwrittenFiles(e,t){for(let n of t??[])e.warning(`Overwrote ${n}`)}export{installScaffoldDependencies,reportOverwrittenFiles};